function normalizeCategory(c) {
  if (!c) return '';
  const s = String(c).toUpperCase().trim();
  if (s.includes('GEN') || s.includes('OPEN')) return 'GENERAL';
  if (s.includes('OBC')) return 'OBC';
  if (s.includes('SC')) return 'SC';
  if (s.includes('ST')) return 'ST';
  if (s.includes('EWS')) return 'EWS';
  return s;
}

function normalizeOccupation(s) {
  if (!s) return '';
  const l = String(s).toLowerCase().trim();
  if (l.includes('farm') || l.includes('agri') || l.includes('kisan') || l.includes('krishi')) return 'farmer';
  if (l.includes('self') || l.includes('entrepreneur') || l.includes('business') || l.includes('startup') || l.includes('artisan') || l.includes('vendor')) return 'self-employed';
  if (l.includes('salar') || l.includes('employ') || l.includes('job') || l.includes('worker')) return 'salaried';
  if (l.includes('student')) return 'student';
  if (l.includes('unemploy')) return 'unemployed';
  return l;
}

function getEducationRank(s) {
  if (!s) return 0;
  const l = String(s).toLowerCase().trim();
  if (l.includes('doctor') || l.includes('phd')) return 6;
  if (l.includes('postgrad') || l.includes('master')) return 5;
  if (l.includes('graduat') || l.includes('degree') || l.includes('bachelor') || l.includes('college')) return 4;
  if (l.includes('diploma') || l.includes('polytechnic')) return 3;
  if (l.includes('12th') || l.includes('hsc') || l.includes('post-matric') || l.includes('class 12') || l.includes('class 11')) return 2;
  if (l.includes('10th') || l.includes('ssc') || l.includes('matric') || l.includes('class 1-10')) return 1;
  return 0;
}

export function evaluateSchemeRules(scheme, profile = DEMO_PROFILE) {
  const rules = RULES_BY_SCHEME[scheme.schemeId] || [];
  if (rules.length === 0) {
    return { verdict: 'STRONG', missing: [] };
  }

  // Calculate age
  let userAge = 19;
  if (profile.dateOfBirth) {
    const parts = profile.dateOfBirth.split('-');
    if (parts.length === 3) {
      const birthYear = parseInt(parts[0], 10);
      userAge = Math.max(0, 2026 - birthYear);
    }
  }

  let passCount = 0;
  let failCount = 0;
  let hardDisqualified = false;
  const missing = [];

  for (const rule of rules) {
    const attr = rule.attributeName;
    const op = rule.operator;
    const val = rule.value;
    let passed = false;

    if (attr === 'age') {
      const targetAge = parseInt(val, 10);
      if (op === '>=') passed = userAge >= targetAge;
      else if (op === '<=') passed = userAge <= targetAge;
      else if (op === '=') passed = userAge === targetAge;
      if (!passed) {
        if (op === '<=' && userAge > targetAge + 5) hardDisqualified = true;
        if (op === '>=' && userAge < targetAge - 5) hardDisqualified = true;
      }
    } else if (attr === 'annual_income') {
      const inc = Number(profile.annualIncome ?? 70000);
      const targetInc = parseFloat(val);
      if (op === '<=') passed = inc <= targetInc;
      else if (op === '>=') passed = inc >= targetInc;
    } else if (attr === 'gender') {
      const uGender = (profile.gender || 'MALE').toUpperCase().trim();
      const rGender = val.toUpperCase().trim();
      passed = op === '!=' ? uGender !== rGender : uGender === rGender;
      if (!passed) hardDisqualified = true;
    } else if (attr === 'state') {
      const uState = (profile.state || 'Maharashtra').toLowerCase().trim();
      const rState = val.toLowerCase().trim();
      passed = rState === 'all india' || rState === 'national' || rState === 'central' || uState === rState;
      if (!passed) hardDisqualified = true;
    } else if (attr === 'category') {
      const uCat = normalizeCategory(profile.category || 'OBC');
      if (op === 'IN') {
        const allowed = val.split(',').map(s => normalizeCategory(s));
        passed = allowed.includes(uCat);
      } else {
        passed = normalizeCategory(val) === uCat;
      }
    } else if (attr === 'occupation') {
      const uOcc = normalizeOccupation(profile.occupation || 'student');
      const rOcc = normalizeOccupation(val);
      passed = uOcc === rOcc || uOcc.includes(rOcc) || rOcc.includes(uOcc);
    } else if (attr === 'education_level') {
      const uEd = getEducationRank(profile.educationLevel || '12th');
      const rEd = getEducationRank(val);
      passed = uEd >= rEd;
    } else if (attr === 'is_bpl') {
      passed = Boolean(profile.isBpl) === (val.toUpperCase() === 'TRUE');
    } else if (attr === 'is_minority') {
      passed = Boolean(profile.isMinority) === (val.toUpperCase() === 'TRUE');
    } else if (attr === 'disability_status') {
      passed = Boolean(profile.disabilityStatus) === (val.toUpperCase() === 'TRUE');
    } else {
      passed = true;
    }

    if (passed) {
      passCount++;
    } else {
      failCount++;
      missing.push(rule.ruleDescription || attr);
    }
  }

  if (hardDisqualified || (rules.length === 1 && failCount > 0) || failCount > 1) {
    return { verdict: 'NOT_MATCHED', missing: [] };
  }
  if (failCount === 0) {
    return { verdict: 'STRONG', missing: [] };
  }
  if (passCount > 0 && failCount === 1) {
    return { verdict: 'PARTIAL', missing };
  }
  return { verdict: 'NOT_MATCHED', missing: [] };
}

export function getFallbackMatches(profile = DEMO_PROFILE) {
  const matches = [];
  for (const scheme of ALL_SCHEMES) {
    const { verdict, missing } = evaluateSchemeRules(scheme, profile);
    if (verdict === 'STRONG' || verdict === 'PARTIAL') {
      matches.push({
        scheme: {
          schemeId: scheme.schemeId,
          name: scheme.name,
          ministry: scheme.ministry,
          categoryName: scheme.categoryName,
          state: scheme.state,
          benefitSummary: scheme.benefitSummary,
          benefitAmount: scheme.benefitAmount,
          deadline: scheme.deadline,
          verifiedAt: scheme.verifiedAt
        },
        confidence: verdict,
        missingFields: missing
      });
    }
  }

  // Sort STRONG first, then deadline, then category
  matches.sort((a, b) => {
    if (a.confidence === 'STRONG' && b.confidence === 'PARTIAL') return -1;
    if (a.confidence === 'PARTIAL' && b.confidence === 'STRONG') return 1;
    return (a.scheme.deadline || '9999').localeCompare(b.scheme.deadline || '9999');
  });

  const byCategory = {};
  for (const m of matches) {
    const cat = m.scheme.categoryName || 'Other';
    if (!byCategory[cat]) byCategory[cat] = [];
    byCategory[cat].push(m);
  }

  return {
    totalMatches: matches.length,
    byCategory
  };
}

